1	export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
2	
3	function JsonLd({ data }: { data: Record<string, unknown> }) {
4	  return (
5	    <script
6	      type="application/ld+json"
7	      // JSON.stringify output is safe to inline; no user input here.
8	      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
9	    />
10	  );
11	}
12	
13	/** Organization + WebSite (with site search) — rendered once in the root layout. */
14	export async function OrganizationJsonLd() {
15	  // sameAs ties "Nxeon" the brand to its social profiles in Google's entity graph —
16	  // the strongest signal for the brand knowledge panel. Read from admin settings so
17	  // it stays in sync with the marketing footer; only real http(s) URLs are included.
18	  let sameAs: string[] = [];
19	  try {
20	    const { getSetting } = await import("@/lib/settings");
21	    const urls = await Promise.all([
22	      getSetting("social_facebook", ""),
23	      getSetting("social_instagram", ""),
24	      getSetting("social_linkedin", ""),
25	      getSetting("social_youtube", ""),
26	      getSetting("social_twitter", ""),
27	      getSetting("social_github", ""),
28	    ]);
29	    sameAs = urls.map((u) => u.trim()).filter((u) => /^https?:\/\//i.test(u));
30	  } catch {
31	    /* settings unavailable — emit an empty sameAs rather than fail the layout */
32	  }
33	  return (
34	    <>
35	      <JsonLd
36	        data={{
37	          "@context": "https://schema.org",
38	          "@type": "Organization",
39	          name: "Nxeon",
40	          url: APP_URL,
41	          // A raster logo (min 112x112) is what Google uses for the brand/knowledge
42	          // panel — an SVG favicon is not eligible. /logo.png is the same mark the
43	          // portal renders.
44	          logo: `${APP_URL}/logo.png`,
45	          description:
46	            "Cloud VPS hosting, game servers, and domains with instant deployment and full root access.",
47	          contactPoint: {
48	            "@type": "ContactPoint",
49	            contactType: "customer support",
50	            url: `${APP_URL}/contact`,
51	          },
52	          sameAs,
53	        }}
54	      />
55	      <JsonLd
56	        data={{
57	          "@context": "https://schema.org",
58	          "@type": "WebSite",
59	          name: "Nxeon",
60	          url: APP_URL,
61	          potentialAction: {
62	            "@type": "SearchAction",
63	            target: `${APP_URL}/domains?q={search_term_string}`,
64	            "query-input": "required name=search_term_string",
65	          },
66	        }}
67	      />
68	    </>
69	  );
70	}
71	
72	/** Product + offers for the pricing page. */
73	export function ProductJsonLd({
74	  plans,
75	}: {
76	  plans: Array<{ name: string; priceCents: number }>;
77	}) {
78	  const offers = plans.map((p) => ({
79	    "@type": "Offer",
80	    name: `${p.name} VPS`,
81	    price: (p.priceCents / 100).toFixed(2),
82	    priceCurrency: "USD",
83	    availability: "https://schema.org/InStock",
84	    url: `${APP_URL}/pricing`,
85	  }));
86	  return (
87	    <JsonLd
88	      data={{
89	        "@context": "https://schema.org",
90	        "@type": "Product",
91	        name: "Nxeon Cloud VPS",
92	        description:
93	          "NVMe cloud VPS with full root access, one-click apps, game servers, and an optional dedicated IPv4.",
94	        brand: { "@type": "Brand", name: "Nxeon" },
95	        offers: {
96	          "@type": "AggregateOffer",
97	          priceCurrency: "USD",
98	          lowPrice: plans.length ? (Math.min(...plans.map((p) => p.priceCents)) / 100).toFixed(2) : undefined,
99	          offerCount: plans.length,
100	          offers,
101	        },
102	      }}
103	    />
104	  );
105	}
106	
107	/**
108	 * Product + offers for a non-VPS product line (shared hosting, game servers).
109	 * Kept alongside the VPS-specific ProductJsonLd so each product line can emit a
110	 * distinct Product entity with its own name/description/url. Prices are in USD
111	 * dollars (e.g. 3.99); NaN/zero offers are dropped so we never advertise a price
112	 * we don't charge.
113	 */
114	export function ProductOffersJsonLd({
115	  name,
116	  description,
117	  url,
118	  offers,
119	}: {
120	  name: string;
121	  description: string;
122	  url: string;
123	  offers: Array<{ name: string; price: number }>;
124	}) {
125	  const priced = offers.filter((o) => Number.isFinite(o.price) && o.price > 0);
126	  return (
127	    <JsonLd
128	      data={{
129	        "@context": "https://schema.org",
130	        "@type": "Product",
131	        name,
132	        description,
133	        brand: { "@type": "Brand", name: "Nxeon" },
134	        offers: {
135	          "@type": "AggregateOffer",
136	          priceCurrency: "USD",
137	          lowPrice: priced.length ? Math.min(...priced.map((o) => o.price)).toFixed(2) : undefined,
138	          offerCount: priced.length,
139	          offers: priced.map((o) => ({
140	            "@type": "Offer",
141	            name: o.name,
142	            price: o.price.toFixed(2),
143	            priceCurrency: "USD",
144	            availability: "https://schema.org/InStock",
145	            url,
146	          })),
147	        },
148	      }}
149	    />
150	  );
151	}
152	
153	/** FAQ rich-result markup. Pass Q/A pairs. */
154	export function FaqJsonLd({ items }: { items: Array<{ q: string; a: string }> }) {
155	  return (
156	    <JsonLd
157	      data={{
158	        "@context": "https://schema.org",
159	        "@type": "FAQPage",
160	        mainEntity: items.map((i) => ({
161	          "@type": "Question",
162	          name: i.q,
163	          acceptedAnswer: { "@type": "Answer", text: i.a },
164	        })),
165	      }}
166	    />
167	  );
168	}
169	
170	/** Article markup for blog posts. */
171	export function ArticleJsonLd({
172	  title,
173	  description,
174	  slug,
175	  published,
176	  updated,
177	  author,
178	  image,
179	}: {
180	  title: string;
181	  description: string;
182	  slug: string;
183	  published: string;
184	  updated: string;
185	  author: string;
186	  /** Absolute or root-relative cover image URL, if the post has one. */
187	  image?: string | null;
188	}) {
189	  const url = `${APP_URL}/blog/${slug}`;
190	  // Normalise a root-relative cover to an absolute URL — Google requires an
191	  // absolute image URL in the Article markup.
192	  const imageUrl = image ? (image.startsWith("http") ? image : `${APP_URL}${image}`) : undefined;
193	  return (
194	    <JsonLd
195	      data={{
196	        "@context": "https://schema.org",
197	        "@type": "BlogPosting",
198	        headline: title,
199	        description,
200	        url,
201	        // Ties the rich result to this exact canonical page.
202	        mainEntityOfPage: { "@type": "WebPage", "@id": url },
203	        ...(imageUrl ? { image: imageUrl } : {}),
204	        datePublished: published,
205	        dateModified: updated,
206	        author: { "@type": "Organization", name: author },
207	        publisher: {
208	          "@type": "Organization",
209	          name: "Nxeon",
210	          logo: { "@type": "ImageObject", url: `${APP_URL}/logo.png` },
211	        },
212	      }}
213	    />
214	  );
215	}
