1	import type { Metadata } from "next";
2	import Link from "next/link";
3	import { notFound } from "next/navigation";
4	import { RowHeader, Section, SectionTitle } from "@/components/marketing/primitives";
5	import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
6	import { ModCarouselRow } from "@/components/mods/ModCarouselRow";
7	import { ModCard } from "@/components/mods/ModCard";
8	import { PlanConfigurator } from "@/components/marketing/gamelanding/PlanConfigurator";
9	import { PREVIEW_GAMES, type PreviewGame } from "@/components/marketing/gamelanding/data";
10	import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
11	import { GAME_URL_SLUG } from "@/lib/marketing/gameLocationLandings";
12	import {
13	  listCatalogFamilies,
14	  listCategoryCounts,
15	  queryCatalogMods,
16	  listFeaturedMods,
17	  listTopDownloadedMods,
18	  listRecentlyUpdatedMods,
19	  listTopRatedMods,
20	  totalDownloadsFor,
21	  formatDownloads,
22	  type ModSummary,
23	} from "@/lib/mods-catalog";
24	
25	export const dynamic = "force-dynamic";
26	
27	const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
28	function parseSort(v?: string): SortKey {
29	  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
30	}
31	
32	/**
33	 * A real per-game NxLabs landing page — item 7 of the NxLabs brief. Only
34	 * rendered for families that actually have catalogued mods (real
35	 * listCatalogFamilies() rows), never a placeholder page for a game with
36	 * nothing in it.
37	 */
38	export async function generateStaticParams(): Promise<Array<{ family: string }>> {
39	  const families = await listCatalogFamilies();
40	  return families.map((f) => ({ family: f.family }));
41	}
42	
43	export async function generateMetadata({ params }: { params: Promise<{ family: string }> }): Promise<Metadata> {
44	  const { family } = await params;
45	  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
46	  return {
47	    title: `${label} Mods & Plugins — NxLabs`,
48	    description: `Browse verified ${label} mods and plugins with real download counts, licenses, and version support — download free, or add straight to your Nxeon server.`,
49	    alternates: { canonical: `/mods/games/${family}` },
50	  };
51	}
52	
53	type Search = { q?: string; sort?: string; category?: string; page?: string };
54	
55	export default async function GameModsMarketingPage({
56	  params,
57	  searchParams,
58	}: {
59	  params: Promise<{ family: string }>;
60	  searchParams: Promise<Search>;
61	}) {
62	  const { family } = await params;
63	  const families = await listCatalogFamilies();
64	  const entry = families.find((f) => f.family === family);
65	  if (!entry) notFound();
66	
67	  const sp = await searchParams;
68	  const q = (sp.q ?? "").trim();
69	  const sort = parseSort(sp.sort);
70	  const category = sp.category?.trim() || undefined;
71	  const page = Number(sp.page) || 1;
72	
73	  const [categoryCounts, result, totalDownloads, featuredMods, topDownloaded, recentlyUpdated, topRated] = await Promise.all([
74	    listCategoryCounts(family),
75	    queryCatalogMods({ family, category, q, sort, page }),
