/**
 * BreadcrumbList rich-result markup for a single-level "Home › Page" trail.
 * Extracted from the inline version already used by app/(marketing)/[slug]/
 * page.tsx (the game×location matrix) so the ~40 hand-built flagship
 * `/[game]-server-hosting` pages can emit the same schema without copy-pasting
 * the JSON-LD shape.
 */
export function BreadcrumbJsonLd({ name, url }: { name: string; url: string }) {
  return (
    <JsonLd
      data={{
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        itemListElement: [
          { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
          { "@type": "ListItem", position: 2, name, item: url },
        ],
      }}
    />
  );
}

