// Wave 12 (2026-09-24) new-game families — each queried by its own
// osTemplate.family so the price shown is that family's own real lowest
// active GamePlan, never a guess or a copy of another family's number.
const NEW_FAMILIES = ["armareforger", "cs16", "ets2", "ats", "dayz"] as const;

const [vpsPlans, hostingPlans, emailPlans, gamePlans, newFamilyPlans] = await Promise.all([
  db.plan.findMany({ where: { active: true }, select: { priceCents: true } }).catch(() => []),
  db.hostingPlan.findMany({ where: { active: true }, select: { priceCents: true } }).catch(() => []),
  db.emailPlan
    .findMany({ where: { active: true }, select: { priceCents: true, termMonths: true } })
    .catch(() => []),
  db.gamePlan
    .findMany({ where: { active: true }, select: { priceCents: true, termMonths: true } })
    .catch(() => []),
  db.gamePlan
    .findMany({
      where: { active: true, osTemplate: { family: { in: [...NEW_FAMILIES] } } },
      select: { priceCents: true, termMonths: true, osTemplate: { select: { family: true } } },
    })
    .catch(() => []),
]);

const vpsFrom = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;
const hostingFrom = hostingPlans.length ? Math.min(...hostingPlans.map((p) => p.priceCents)) : null;
const emailFrom = emailPlans.length ? Math.min(...emailPlans.map(monthlyOf)) : null;
const gameFrom = gamePlans.length ? Math.min(...gamePlans.map(monthlyOf)) : null;

const newFamilyFrom = (family: string): number | null => {
  const rows = newFamilyPlans.filter((p) => p.osTemplate.family === family);
  return rows.length ? Math.min(...rows.map(monthlyOf)) : null;
};

