64	  const relatedPosts = await getRelatedPosts(post, 3);
65	  const product = productLinkForPost(post);
66	  const mins = readMinutes(post.body);
67	
68	  // GEO "quick answer": a direct one-liner answer engines can lift, plus a few
69	  // genuinely useful facts pulled from the real post fields.
70	  const answer = (post.excerpt || firstParagraph(post.body)).trim();
71	  const facts: QuickFact[] = [
72	    { label: "Topic", value: post.category },
