91	    coverImage: r.coverImage,
92	    iconName: iconForPost(r),
93	  }));
94	
95	  return (
96	    <div className="flex min-h-screen flex-col">
97	      <MarketingHeader />
98	      <main className="flex-1">
99	        <ArticleJsonLd
